export const AttendeeResponseStatusSchema = z.enum([
  "needsAction",
  "accepted",
  "declined",
  "tentative",
]);
export type AttendeeResponseStatus = z.infer<typeof AttendeeResponseStatusSchema>;

const ATTENDEE_STATUS_DOT: Record<AttendeeResponseStatus, string> = {
  accepted: "bg-success",
  declined: "bg-error",
  tentative: "bg-warning",
  needsAction: "bg-text-subtle",
};

const attendeeStatusLabel = (status: AttendeeResponseStatus): string =>
  status === "needsAction" ? "hasn't responded" : status;

export const EVENT_ALLDAY_HEIGHT = 20;
export const GRID_EVENT_TIME_LABEL_LINE_HEIGHT = 13;
export const GRID_EVENT_TITLE_LINE_HEIGHT_PX = 16;
export const GRID_EVENT_TITLE_VERTICAL_SLACK_PX = 7;
export const COMPACT_EVENT_MAX_HEIGHT = 15;
export const MIN_EVENT_HEIGHT_FOR_TIME_LABEL = 36;
export const MIN_EVENT_WIDTH_FOR_TIME_LABEL = 90;

import { darken } from "@web/common/styles/color.utils";
import { RepeatIcon } from "@web/components/Icons/Repeat";

interface Props {
  baseColor: string;
}

/** ...doc comment... */
